-- Ejecutar una vez en Supabase > SQL Editor. Conserva las rachas y el problema de hoy.
begin;

alter table public.desafios_diarios drop constraint if exists desafios_diarios_rating_check;
alter table public.desafios_diarios add constraint desafios_diarios_rating_check check (rating between 1700 and 4000);
-- El banco se recicla únicamente al agotar el nivel, empezando por el menos reciente.
alter table public.desafios_diarios drop constraint if exists desafios_diarios_puzzle_id_key;
alter table public.desafios_diarios add column if not exists objetivo integer;
alter table public.desafios_diarios add column if not exists racha_base integer;
create index if not exists desafios_diarios_puzzle_historial on public.desafios_diarios(puzzle_id,dia);

create table if not exists public.desafios_banco (
  puzzle_id text primary key check (puzzle_id ~ '^[a-zA-Z0-9]{5}$'),
  rating integer not null check (rating between 1700 and 4000),
  datos jsonb not null,
  fuente text not null default 'https://database.lichess.org/#puzzles',
  check (datos->'puzzle'->>'id'=puzzle_id),
  check ((datos->'puzzle'->>'rating')::integer=rating),
  check (jsonb_typeof(datos->'puzzle'->'solution')='array' and jsonb_array_length(datos->'puzzle'->'solution')%2=1),
  check (datos->'game'->>'fen' is not null)
);
alter table public.desafios_banco enable row level security;
revoke all on public.desafios_banco from public,anon,authenticated;
create index if not exists desafios_banco_rating on public.desafios_banco(rating);

