-- Usa días completos: la jugada de otra persona nunca cambia el problema en curso.
create or replace function public.desafios_nivel(p_dia date)
returns table(racha_base integer,objetivo integer)
language sql stable security definer set search_path=pg_catalog,public as $$
  with dias as (
    select r.usuario_id,r.dia,
      r.dia-(row_number() over(partition by r.usuario_id order by r.dia))::integer as grupo
    from public.desafios_resueltos r
    where r.dia<p_dia and not exists (
      select 1 from public.desafios_fallados f where f.usuario_id=r.usuario_id and f.dia=r.dia
    )
  ), rachas as (
    select count(*)::integer as longitud from dias group by usuario_id,grupo having max(dia)=p_dia-1
  ), lider as (select coalesce(max(longitud),0) as longitud from rachas)
  select longitud,1800+50*greatest(longitud-1,0) from lider;
$$;
revoke all on function public.desafios_nivel(date) from public,anon,authenticated;

create or replace function public.desafios_actualizar()
returns boolean language plpgsql security definer set search_path=pg_catalog,public as $$
declare
  d_dia date := (now() at time zone 'America/Montevideo')::date;
  d_objetivo integer; d_racha integer; d_candidato public.desafios_banco%rowtype;
  d_nivel integer;
begin
  if exists(select 1 from public.desafios_diarios where dia=d_dia) then return true; end if;
  if not pg_try_advisory_xact_lock(18300407) then return false; end if;
  if exists(select 1 from public.desafios_diarios where dia=d_dia) then return true; end if;
  select racha_base,objetivo into d_racha,d_objetivo from public.desafios_nivel(d_dia);
  -- Rating Lichess real, dentro del tramo de 50 más cercano al objetivo.
  select (round(rating/50.0)*50)::integer into d_nivel from public.desafios_banco
    order by abs((round(rating/50.0)*50)::integer-d_objetivo),abs(rating-d_objetivo),puzzle_id limit 1;
  select b.* into d_candidato from public.desafios_banco b
    left join (select puzzle_id,max(dia) as ultimo from public.desafios_diarios group by puzzle_id) h using(puzzle_id)
    where (round(b.rating/50.0)*50)::integer=d_nivel
    order by h.ultimo nulls first,md5(b.puzzle_id||d_dia::text) limit 1;
  if d_candidato.puzzle_id is null then return false; end if;
  insert into public.desafios_diarios(dia,puzzle_id,rating,datos,objetivo,racha_base)
    values(d_dia,d_candidato.puzzle_id,d_candidato.rating,d_candidato.datos,d_objetivo,d_racha);
  return true;
end;
$$;
revoke all on function public.desafios_actualizar() from public,anon,authenticated;

create or replace function public.obtener_desafio_diario()
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare d_dia date := (now() at time zone 'America/Montevideo')::date; d_resultado jsonb;
begin
  perform public.desafios_actualizar();
  select jsonb_build_object('fecha',dia::text,'datos',datos,'objetivo',objetivo,'racha_base',racha_base)
    into d_resultado from public.desafios_diarios where dia=d_dia;
  return d_resultado;
end;
$$;
revoke all on function public.obtener_desafio_diario() from public;
grant execute on function public.obtener_desafio_diario() to anon,authenticated;

-- Conserva el mismo trabajo automático, sin duplicarlo ni depender de llamadas a Lichess.
select cron.schedule('atlantida-desafio-diario','5 * * * *','select public.desafios_actualizar();');
select public.desafios_actualizar();
notify pgrst, 'reload schema';
commit;
